    thousands_sep = thousands_separator()
    decimal_sep = decimal_separator()
    if isinstance(value, str):
        value = value.replace(thousands_sep, "").replace(decimal_sep, ".")
        if "." not in value:
            # Parse integer strings with `int()` so that arbitrarily large
            # values never go through a lossy, overflowing `float()` conversion.
            try:
                value = int(value)
            except ValueError:
                try:
                    float_value = float(value)
                except (TypeError, ValueError):
                    return str(value)
                if not math.isfinite(float_value):
                    return _format_not_finite(float_value)
                # e.g. "1e5": not an integer, keep the previous behaviour.
                return str(value)
