            try:
                float_value = float(value)
            except (TypeError, ValueError):
                return str(value)
            if not math.isfinite(float_value):
                return _format_not_finite(float_value)
            value = float_value
    elif not isinstance(value, int):
        try:
            float_value = float(value)
        except (TypeError, ValueError):
            return str(value)
        if not math.isfinite(float_value):
            return _format_not_finite(float_value)

    if isinstance(value, int):
        # Integers of any magnitude (including bool) are formatted directly.
        result = f"{value:,}"
        if ndigits is not None and ndigits > 0:
            result += "." + "0" * ndigits
    elif ndigits is not None:
        result = f"{value:,.{ndigits}f}"
    else:
        result = f"{value:,}"
    if thousands_sep != "," or decimal_sep != ".":
        result = result.translate(str.maketrans(",.\", thousands_sep + decimal_sep))
    return result
'''

